//! Account sync excludes device grants, paths, credentials and memory.
use serde_json::{json,Value};
const KEYS:&[&str]=&["rsLanguage","rsWorkMode","rsThinkingLevel","rsSounds","rsExtraThinking","rsShowApproach","rsPlanMode","rsAppearance","rsVisualCheck","rsContinuationOffer","rsInputLimitEnabled","rsInputCharLimit","rsOutputLimitEnabled","rsOutputCharLimit","rsForgeMode","rsAutoFix"];
static SERIAL:tokio::sync::Mutex<()>=tokio::sync::Mutex::const_new(());
static STATUS:once_cell::sync::Lazy<std::sync::RwLock<std::collections::BTreeMap<String,String>>>=once_cell::sync::Lazy::new(Default::default);
pub fn status(id:&str)->String{STATUS.read().unwrap_or_else(|e|e.into_inner()).get(id).cloned().unwrap_or_else(||"Waiting to sync".into())}
fn settings(value:Value)->Value{Value::Object(value.as_object().into_iter().flatten().filter(|(key,_)|KEYS.contains(&key.as_str())).map(|(k,v)|(k.clone(),v.clone())).collect())}
fn merge(base:&Value,local:&Value,remote:&Value)->Value{let mut out=remote.as_object().cloned().unwrap_or_default();let keys:std::collections::BTreeSet<_>=base.as_object().into_iter().flatten().map(|(k,_)|k).chain(local.as_object().into_iter().flatten().map(|(k,_)|k)).collect();for key in keys{if base.get(key)!=local.get(key){if let Some(v)=local.get(key){out.insert(key.clone(),v.clone());}else{out.remove(key);}}}Value::Object(out)}
async fn snapshot(state:&crate::AppState)->anyhow::Result<Value>{Ok(json!({"settings":settings(serde_json::to_value(state.preferences.snapshot())?),"skills":crate::skills::account_export().await?}))}
pub async fn run(state:&crate::AppState)->anyhow::Result<()>{let _serial=SERIAL.lock().await;let Some(active)=state.accounts.active()else{return Ok(())};let result=sync(state).await;STATUS.write().unwrap_or_else(|e|e.into_inner()).insert(active.id.clone(),if result.is_ok(){"Up to date"}else{"Offline or unable to sync — changes are saved on this computer"}.into());let appearance=serde_json::to_value(state.preferences.snapshot())?["rsAppearance"].clone();let _=state.accounts.cache_appearance(appearance).await;result}
async fn sync(state:&crate::AppState)->anyhow::Result<()>{let path=crate::profile_paths::data_root().join("account-sync.json");let local=snapshot(state).await?;let baseline=match std::fs::read(&path){Ok(bytes)=>serde_json::from_slice::<Value>(&bytes)?,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>json!({"settings":settings(serde_json::to_value(crate::preferences::DesktopPreferences::default())?),"skills":{}}),Err(e)=>return Err(e.into())};
 for _ in 0..3{let remote=state.accounts.cloud_read().await?;let document=&remote["document"];anyhow::ensure!(document["settings"].is_object()&&document["skills"].is_object(),"Invalid cloud document");let merged=json!({"settings":merge(&baseline["settings"],&local["settings"],&settings(document["settings"].clone())),"skills":merge(&baseline["skills"],&local["skills"],&document["skills"])});crate::skills::validate_account_document(&merged["skills"])?;
 if merged!=*document{match state.accounts.cloud_write(remote["revision"].as_u64().ok_or_else(||anyhow::anyhow!("Invalid sync revision"))?,merged.clone()).await{Ok(_)=>{},Err(e)if e.downcast_ref::<crate::accounts::AccountError>().is_some_and(|e|e.status==409)=>continue,Err(e)=>return Err(e)}}
 let current=snapshot(state).await?;let mut patch=serde_json::Map::new();for key in KEYS{if current["settings"].get(*key)==local["settings"].get(*key){if let Some(value)=merged["settings"].get(*key){patch.insert((*key).into(),value.clone());}}}state.preferences.patch(Value::Object(patch))?;crate::skills::account_apply(&local["skills"],&merged["skills"]).await?;let temporary=path.with_extension("json.tmp");std::fs::write(&temporary,serde_json::to_vec(&merged)?)?;if path.exists(){std::fs::remove_file(&path)?;}std::fs::rename(temporary,path)?;return Ok(());}anyhow::bail!("Account changed on another device; sync will retry")}
#[cfg(test)]mod tests{use super::*;#[test]fn merge_preserves_remote_edits_and_local_deletions(){assert_eq!(merge(&json!({"a":1,"b":1,"deleted":1}),&json!({"a":2,"b":1,"new":3}),&json!({"a":1,"b":2,"deleted":1,"remote":4})),json!({"a":2,"b":2,"new":3,"remote":4}));assert_eq!(merge(&json!({"a":1}),&json!({"a":1}),&json!({})),json!({}));}#[test]fn excludes_device_grants_paths_and_secrets(){assert_eq!(settings(json!({"rsLanguage":"fr","rsPermMode":"full","rsAllowedFolders":["/private"],"token":"secret","rsApprovalMode":"bypass"})),json!({"rsLanguage":"fr"}));}}
